"""Parser for pages generated by Trefik SW, the tournament software used by stiga.trefik.cz (Czech) and
galdahokejs.lv (Latvia).

A Trefik SW tournament has
- a main page (``index.aspx`` / ``index.htm``) with the title and date ("Cheb, 23. listopad 2024"), links to
  the other pages, and the final table (player names, sometimes linked with Trefik's ``idpl``);
- a groups page (``kriz.aspx`` / ``kriz.htm``) with one cross-table per group, basic groups first and final
  (placement) groups after; newer versions add per-round tables with full names below each cross-table;
- a placement/play-off page (``*_playoff.aspx``, ``*_umisteni.aspx``, ``umisteni.htm``) listing every series
  with each game's score; "P" marks a game decided in overtime / penalties;
- for international events a participants list (``*_list.aspx`` / ``*_wr.aspx``) linking players to ITHF ids.

Cross-table cells hold the row player's score first. Each game appears twice (row A col B and row B col A), so
only cells above the diagonal are read. Cells marked "K" in final groups are results carried over from the
basic groups and are skipped (the game is already emitted with the basic group). Double round robins show
"8:1 + 7:1" in one cell.
"""

from __future__ import annotations

import re
import unicodedata
from dataclasses import dataclass, field
from datetime import date
from urllib.parse import parse_qs, unquote, urljoin, urlsplit

from bs4 import BeautifulSoup, Tag

# -------------------------------------------------------------------------------------------------
# Dates
# -------------------------------------------------------------------------------------------------

_MONTHS = {
    # Czech, nominative and genitive
    "leden": 1, "ledna": 1, "unor": 2, "unora": 2, "brezen": 3, "brezna": 3, "duben": 4, "dubna": 4,
    "kveten": 5, "kvetna": 5, "cerven": 6, "cervna": 6, "cervenec": 7, "cervence": 7, "srpen": 8, "srpna": 8,
    "zari": 9, "rijen": 10, "rijna": 10, "listopad": 11, "listopadu": 11, "prosinec": 12, "prosince": 12,
    # Latvian (nominative and genitive / locative)
    "janvaris": 1, "janvari": 1, "februaris": 2, "februari": 2, "marts": 3, "marta": 3, "aprilis": 4,
    "aprili": 4, "maijs": 5, "maija": 5, "junijs": 6, "junija": 6, "julijs": 7, "julija": 7, "augusts": 8,
    "augusta": 8, "septembris": 9, "septembri": 9, "oktobris": 10, "oktobri": 10, "novembris": 11,
    "novembri": 11, "decembris": 12, "decembri": 12,
    # English
    "january": 1, "february": 2, "march": 3, "april": 4, "may": 5, "june": 6, "july": 7, "august": 8,
    "september": 9, "october": 10, "november": 11, "december": 12,
}


def ascii_fold(text: str) -> str:
    text = unicodedata.normalize("NFKD", text)
    return "".join(c for c in text if not unicodedata.combining(c)).lower()


def parse_date_text(text: str) -> date | None:
    """'Cheb, 23. listopad 2024' / '22. dubna 2023' / '12. - 13.6.2004' / '18.4.2026' -> date (first day)."""
    folded = ascii_fold(text)
    m = re.search(r"(\d{1,2})\.\s*([a-z]+)\s+(\d{4})", folded)
    if m and m.group(2) in _MONTHS:
        return _safe_date(int(m.group(3)), _MONTHS[m.group(2)], int(m.group(1)))
    m = re.search(r"(\d{1,2})\.\s*(?:-\s*\d{1,2}\.\s*)?(\d{1,2})\.\s*(\d{4})", folded)
    if m:
        return _safe_date(int(m.group(3)), int(m.group(2)), int(m.group(1)))
    m = re.search(r"(\d{1,2})\.\s*-\s*\d{1,2}\.\s*(\d{1,2})\.\s*(\d{4})", folded)
    if m:
        return _safe_date(int(m.group(3)), int(m.group(2)), int(m.group(1)))
    return None


def _safe_date(y: int, m: int, d: int) -> date | None:
    try:
        return date(y, m, d)
    except ValueError:
        return None


# -------------------------------------------------------------------------------------------------
# Names
# -------------------------------------------------------------------------------------------------

_SUFFIX = {"ml", "st", "jr", "sr", "ml.", "st."}


def clean_name(text: str) -> str:
    text = text.replace("\xa0", " ")
    text = re.sub(r"\([^()]*\d[^()]*\)", " ", text)  # seeding "(12)", "(A1/4)"
    text = re.sub(r"^\s*-\s*", "", text)       # "- Kobrle Michal" on play-off pages
    return " ".join(text.split()).strip(" *")


def _tokens(text: str) -> list[str]:
    return [t for t in re.split(r"[\s.]+", ascii_fold(text)) if t]


def abbrev_matches(abbrev: str, full: str, strict: bool = False) -> bool:
    """Does a cross-table label ('Kr Lebl', 'L.Turoň', 'Zd Matoušek ml.') fit a full name
    ('Lebl Kryštof', 'Matoušek ml. Zdeněk' - surname first)? ``strict`` turns off the written-out nickname rule
    ('Vojta' = 'Vojtěch'), so 'Mark Ābele' fits 'Ābele Markuss' but not 'Ābele Margarita'."""
    a = _tokens(abbrev)
    f = _tokens(full)
    if not a or not f:
        return False
    if a == f or sorted(a) == sorted(f):
        return True
    prefix, rest = a[0], a[1:]
    if not rest:
        return False
    raw_prefix = re.split(r"[\s.]+", abbrev.strip())[0]
    if prefix in ("m", "ml", "st", "s") and raw_prefix.islower():  # 'ml Chylík' / 'm.Chylík' = Chylík ml.
        suffix = "ml" if prefix.startswith("m") else "st"
        f_core = [t for t in f if t not in _SUFFIX]
        return suffix in f and len(rest) == 1 and rest[0] in f_core[:-1]
    rest_core = [t for t in rest if t not in _SUFFIX]
    rest_suffix = [t for t in rest if t in _SUFFIX]
    f_core = [t for t in f if t not in _SUFFIX]
    f_suffix = [t for t in f if t in _SUFFIX]
    if rest_suffix and rest_suffix != f_suffix:
        return False  # 'ml.' on the label must be on the full name too (the label may leave it out)
    # the surname is every full-name token except the first name(s); try each split
    for k in range(1, len(f_core)):
        surname, first = f_core[:k], f_core[k:]
        if surname == rest_core and _first_ok(first[0], prefix, strict):
            return True
        # some pages put the first name first: "Rainers Kalninš"
        first2, surname2 = f_core[: len(f_core) - k], f_core[len(f_core) - k:]
        if surname2 == rest_core and _first_ok(first2[0], prefix, strict):
            return True
    return False


def _first_ok(first: str, prefix: str, strict: bool = False) -> bool:
    """'Kr' fits 'kryštof'; a written-out nickname 'Vojta' fits 'Vojtěch' (same first three letters)."""
    return first.startswith(prefix) or (not strict and len(prefix) >= 4 and first[:3] == prefix[:3])


def display_name(surname_first: str) -> str:
    """'Matoušek ml. Zdeněk' -> 'Zdeněk Matoušek ml.'; 'Plešák, Pavel' -> 'Pavel Plešák'."""
    text = clean_name(surname_first)
    if "," in text:
        last, first = [p.strip() for p in text.split(",", 1)]
        return f"{first} {last}".strip()
    parts = text.split()
    if len(parts) < 2:
        return text
    return " ".join([parts[-1], *parts[:-1]])


# -------------------------------------------------------------------------------------------------
# Scores
# -------------------------------------------------------------------------------------------------

_SCORE = re.compile(r"(\d+)\s*:\s*(\d+)\s*([A-Za-z]*)")


def parse_cell_scores(text: str) -> list[tuple[int, int, str]]:
    """'5:3' -> [(5,3,'')]; '8:8 + 7:3' -> two games; '2:1 K' -> [(2,1,'K')]; '3:2 P' -> [(3,2,'P')]."""
    text = text.replace("\xa0", " ")
    return [(int(a), int(b), flag.upper()) for a, b, flag in _SCORE.findall(text)]


# -------------------------------------------------------------------------------------------------
# Main page
# -------------------------------------------------------------------------------------------------


@dataclass
class FinalTableRow:
    rank: int
    name: str
    club: str
    idpl: int | None = None
    nation: str | None = None  # from "* Latvia" in the club column on international events


@dataclass
class EventPage:
    title: str
    date: date | None
    groups_url: str | None
    playoff_urls: list[str]
    list_urls: list[str]
    final_table: list[FinalTableRow]


def _idpl(href: str) -> int | None:
    q = parse_qs(urlsplit(href).query)
    try:
        return int(q["idpl"][0])
    except (KeyError, ValueError, IndexError):
        return None


def parse_event_page(html: str, url: str) -> EventPage:
    soup = BeautifulSoup(html, "lxml")
    title = ""
    for el in soup.find_all(["h2", "h1", "p", "font", "b"]):
        text = " ".join(el.get_text(" ", strip=True).split())
        if text and parse_date_text(text) and len(text) < 120:
            title = text
            break
    when = parse_date_text(title) if title else None
    groups_url, playoffs, lists = None, [], []
    for a in soup.find_all("a", href=True):
        href = a["href"].strip()
        low = href.lower()
        if "data/" in low or low.startswith(("http", "../")) and "cz_turnaje" not in low:
            continue
        absolute = urljoin(url, href)
        name = low.rsplit("/", 1)[-1]
        if (name.startswith("kriz.") or "_cross." in name) and groups_url is None:
            groups_url = absolute
        elif ("playoff" in name or "umisteni" in name) and absolute not in playoffs:
            playoffs.append(absolute)
        elif re.search(r"_(list|wr)\.aspx$", name) and absolute not in lists:
            lists.append(absolute)
    return EventPage(title, when, groups_url, playoffs, lists, parse_final_table(soup))


def parse_final_table(soup: BeautifulSoup) -> list[FinalTableRow]:
    rows: list[FinalTableRow] = []
    seen: set[str] = set()
    for tr in soup.find_all("tr"):
        tds = tr.find_all("td", recursive=False)
        if len(tds) < 3:
            continue
        texts = [" ".join(td.get_text(" ", strip=True).split()) for td in tds]
        if not re.fullmatch(r"\d+\.", texts[0]):
            continue
        name = clean_name(texts[1])
        if not re.search(r"[^\W\d_]", name) or name in seen:
            continue
        link = tds[1].find("a", href=True)
        club = texts[2]
        nation = club[1:].strip() if club.startswith("*") else None
        seen.add(name)
        rows.append(FinalTableRow(int(texts[0][:-1]), name, club, _idpl(link["href"]) if link else None, nation))
    return rows


def parse_participants(html: str) -> list[tuple[int | None, int | None, str]]:
    """Participants list (``*_list.aspx`` / ``*_wr.aspx``): (idpl, ITHF id, name) for each row that links to
    the ITHF player page."""
    soup = BeautifulSoup(html, "lxml")
    out = []
    for tr in soup.find_all("tr"):
        if tr.find("tr") is not None:
            continue  # a layout row that wraps the whole list: its links belong to many players
        links = tr.find_all("a", href=True)
        idpls = {_idpl(a["href"]) for a in links if "idpl=" in a["href"]}
        ithf_links = [a for a in links if re.search(r"ithf/ranking/player\.aspx", a["href"], re.I)]
        if len(idpls) > 1 or len(ithf_links) > 1:
            continue  # more than one player in one row: an id could be paired with the wrong name
        idpl, ithf, name = None, None, ""
        for a in links:
            href = a["href"]
            if "idpl=" in href:
                idpl = _idpl(href)
                name = name or clean_name(a.get_text(" ", strip=True)) or unquote(
                    parse_qs(urlsplit(href).query).get("p", [""])[0])
            m = re.search(r"ithf/ranking/player\.aspx\?ID=(\d+)", href, re.I)
            if m:
                ithf = int(m.group(1))
                name = name or clean_name(a.get_text(" ", strip=True))
        if ithf is not None or idpl is not None:
            out.append((idpl, ithf, name))
    return out


# -------------------------------------------------------------------------------------------------
# Groups page
# -------------------------------------------------------------------------------------------------


@dataclass
class CrossRow:
    label: str                       # as printed: 'Kr Lebl', 'L.Turoň' or a full name
    cells: list[str]                 # one per column (own column = '*')
    full: str | None = None          # resolved full name (surname first)


@dataclass
class Group:
    phase: str                       # "basic" or "final" (None from the parser when the page has no heading)
    name: str                        # "1", "A", ...
    rows: list[CrossRow]
    # games from the per-round tables (newer pages): (round, full1, full2, score text)
    round_games: list[tuple[int, str, str, str]] = field(default_factory=list)


_PHASE_RE = re.compile(r"^\s*(Basic groups|Final groups?|Placement groups|Základní skupiny|Výkonnostní skupiny"
                       r"|Finálová skupina|Pamata grupas|Fināla grupas?)\b", re.I)
_GROUP_RE = re.compile(r"^\s*(Group|Skupina|Grupa)\s+\S+", re.I)


def _is_heading(text) -> bool:
    """A section heading, not a navigation link to another page/anchor."""
    return bool(_PHASE_RE.match(text)) and text.find_parent("a", href=True) is None


def _phase_of(node: Tag) -> str | None:
    prev = node.find_previous(string=_is_heading)
    if prev is None:
        return None
    text = ascii_fold(str(prev))
    return "final" if ("final" in text or "vykonnost" in text or "placement" in text) else "basic"


def _group_name(node: Tag) -> str:
    """'Group A' -> 'A'. A bare 'Final group' heading closer than any 'Group X' gives ''."""
    prev = node.find_previous(string=lambda t: bool(_GROUP_RE.match(t) or _is_heading(t)))
    if prev is None or not _GROUP_RE.match(prev):
        return ""
    name = str(prev).strip().split(None, 1)[1].strip()
    return re.sub(r"\s+(Group|Skupina|Grupa)$", "", name, flags=re.I)


def parse_groups_page(html: str) -> list[Group]:
    soup = BeautifulSoup(html, "lxml")
    groups: list[Group] = []
    current: Group | None = None
    for table in soup.find_all("table"):
        diag = [td for td in table.find_all("td", class_="kx") if td.find_parent("table") is table]
        if diag:
            rows = []
            for tr in table.find_all("tr", recursive=False) or table.find_all("tr"):
                if tr.find_parent("table") is not table:
                    continue
                tds = tr.find_all("td", recursive=False)
                name_idx = next((i for i, td in enumerate(tds) if "kt" in (td.get("class") or [])), None)
                if name_idx is None:
                    continue
                label = clean_name(tds[name_idx].get_text(" ", strip=True))
                cells = [td.get_text(" ", strip=True) for td in tds[name_idx + 1:]]
                rows.append(CrossRow(label, cells))
            n = len(rows)
            for r in rows:
                r.cells = r.cells[:n]
            current = Group(_phase_of(table), _group_name(table), rows)
            groups.append(current)
            continue
        head = table.find("td", class_="kt", attrs={"colspan": "4"})
        if head is not None and current is not None and head.find_parent("table") is table and not table.find("table"):
            try:
                rnd = int(head.get_text(strip=True))
            except ValueError:
                continue
            for tr in table.find_all("tr"):
                tds = tr.find_all("td")
                if len(tds) == 4 and tds[1].get_text(strip=True) == "-":
                    current.round_games.append((rnd, clean_name(tds[0].get_text(" ", strip=True)),
                                                clean_name(tds[2].get_text(" ", strip=True)),
                                                tds[3].get_text(" ", strip=True)))
    return groups


def resolve_group_names(group: Group, candidates: list[str], exclude: set[str] | frozenset = frozenset()) -> list[str]:
    """Fill ``row.full`` for each cross-table row. Uses the group's own round tables when present (exact
    player set, plus score evidence for ties), else ``candidates`` (the tournament's full names).
    Returns the labels that could not be resolved uniquely."""
    own = sorted({n for _, a, b, _ in group.round_games for n in (a, b)})
    labels = {r.label for r in group.rows}
    # newer pages print full names in the round tables; some (galdahokejs.lv) repeat the short labels
    if own and sum(n in labels for n in own) > len(own) / 2:
        own = []
    pool = own or candidates
    unresolved = []
    taken: set[str] = set()
    for i, row in enumerate(group.rows):
        if row.full:
            taken.add(row.full)
            continue
        options = [c for c in pool if abbrev_matches(row.label, c)]
        if len(options) > 1:
            # 'Marg Ābele' / 'Mark Ābele': a real prefix beats the nickname rule, and a longer full name beats
            # a candidate that is only the same short label seen on another page
            options = [c for c in options if abbrev_matches(row.label, c, strict=True)] or options
            lab = set(_tokens(row.label))
            longer = [c for c in options if (extra := set(_tokens(c)) - lab) and not extra <= _SUFFIX]
            options = longer or options
        if len(options) > 1:
            options = [c for c in options if c not in exclude] or options
        if len(options) > 1 and group.round_games:
            options = [c for c in options if _scores_agree(group, i, c)] or options
        if len(options) > 1:
            options = [c for c in options if c not in taken] or options
        if len(options) == 1:
            row.full = options[0]
            taken.add(options[0])
        else:
            unresolved.append(row.label)
    return unresolved


def resolve_all_groups(groups: list[Group], candidates: list[str], max_passes: int = 3) -> None:
    """Resolve every group of an event; a full name placed in one group of a phase is excluded from the
    ambiguous options of the other groups of that phase (a player is in one basic and one final group)."""
    for _ in range(max_passes):
        placed: dict[str, set[str]] = {}
        for g in groups:
            placed.setdefault(g.phase, set()).update(r.full for r in g.rows if r.full)
        before = sum(1 for g in groups for r in g.rows if r.full)
        for g in groups:
            own = {r.full for r in g.rows if r.full}
            resolve_group_names(g, candidates, placed.get(g.phase, set()) - own)
        if sum(1 for g in groups for r in g.rows if r.full) == before:
            break


def _scores_agree(group: Group, i: int, candidate: str) -> bool:
    row_scores = {tuple(s[:2]) for cell in group.rows[i].cells for s in parse_cell_scores(cell)}
    own = set()
    for _, a, b, score in group.round_games:
        for g1, g2, _ in parse_cell_scores(score):
            if a == candidate:
                own.add((g1, g2))
            elif b == candidate:
                own.add((g2, g1))
    return bool(own) and own <= row_scores | own and len(own & row_scores) >= max(1, len(own) // 2)


def round_lookup(group: Group) -> dict[frozenset, int]:
    """Round number by pair of full names (round tables may print full names or the short row labels)."""
    by_label = {r.label: r.full for r in group.rows if r.full}
    out = {}
    for rnd, a, b, _ in group.round_games:
        out.setdefault(frozenset((by_label.get(a, a), by_label.get(b, b))), rnd)
    return out


# -------------------------------------------------------------------------------------------------
# Play-off / placement page
# -------------------------------------------------------------------------------------------------


@dataclass
class Series:
    label: str                      # "Finals", "1/4", "B Semifinals", ...
    player1: str
    player2: str
    games: list[tuple[int, int, bool]]  # (goals1, goals2, overtime)
    idpl1: int | None = None
    idpl2: int | None = None
    walkover: bool = False              # every game cell marked "K" (kontumace)


_GAME = re.compile(r"^(\d+)\s*:\s*(\d+)\s*(P|SN|OT|PP)?$", re.I)


def parse_playoff_page(html: str) -> list[Series]:
    soup = BeautifulSoup(html, "lxml")
    out: list[Series] = []
    for tr in soup.find_all("tr"):
        tds = tr.find_all("td", recursive=False)
        idx = next((i for i, td in enumerate(tds)
                    if td.get_text(" ", strip=True).replace("\xa0", " ").startswith("- ")), None)
        if idx is None or idx == 0:
            continue
        p1 = clean_name(tds[idx - 1].get_text(" ", strip=True))
        p2 = clean_name(tds[idx].get_text(" ", strip=True))
        if not p1 or not p2:
            continue
        if idx >= 2 and not _GAME.match(tds[0].get_text(" ", strip=True).replace("\xa0", " ").strip()):
            label = " ".join(tds[0].get_text(" ", strip=True).split())
        else:
            th = tr.find_previous("th", class_="hh") or tr.find_previous("th")
            label = " ".join(th.get_text(" ", strip=True).split()) if th else "Play-off"
        games, forfeits = [], 0
        for td in tds[idx + 1:]:
            if td.find("strong") or td.find("b"):
                continue  # series score
            text = " ".join(td.get_text(" ", strip=True).replace("\xa0", " ").split())
            m = _GAME.match(text)
            if m:
                games.append((int(m.group(1)), int(m.group(2)), bool(m.group(3))))
            elif re.match(r"^\d+\s*:\s*\d+\s*K$", text):
                forfeits += 1
        l1, l2 = tds[idx - 1].find("a", href=True), tds[idx].find("a", href=True)
        out.append(Series(label, p1, p2, games, _idpl(l1["href"]) if l1 else None,
                          _idpl(l2["href"]) if l2 else None, forfeits > 0 and not games))
    return out


_ROUND_SIZE = {"final": 1, "finals": 1, "finale": 1, "3rd": 1, "bronze": 1, "semifinal": 2, "semifinals": 2,
               "quarterfinal": 4, "quarterfinals": 4, "eighthfinals": 8,
               # Czech
               "finale": 1, "semifinale": 2, "ctvrtfinale": 4, "osmifinale": 8, "sestnactifinale": 16}


def split_bracket(label: str) -> tuple[str, int]:
    """'B 1/4' -> ('B', 4); 'Finals' -> ('', 1); 'B Semifinals' -> ('B', 2); '4.league 1/2' -> ('4.league', 2)."""
    text = " ".join(label.split())
    m3 = re.search(r"(?:^|\s)(?:o\s*)?3\.?\s*(?:misto|place)$|(?:^|\s)3rd$", ascii_fold(text))
    if m3:  # third-place match: last round of its bracket
        return text[:m3.start()].strip(), 1
    m = re.search(r"1\s*/\s*(\d+)(?:\s*-?\s*finals?|\s*finále)?\s*$", text, re.I)
    if m:
        return text[:m.start()].strip(), int(m.group(1))
    words = text.split()
    if words and ascii_fold(words[-1]) in _ROUND_SIZE:
        return " ".join(words[:-1]), _ROUND_SIZE[ascii_fold(words[-1])]
    return text, 1


# -------------------------------------------------------------------------------------------------
# Collecting every result page of one event
# -------------------------------------------------------------------------------------------------

_RESULT_PAGE = re.compile(r"(kriz|cross|umisteni|playoff|play_off|ranking|_list|_wr|jednotlivci|vysl)[^/]*\.(aspx|htm|html|php)$",
                          re.I)
_CATEGORY_WORDS = [  # (folded link-text fragment, category); order matters
    ("druzstv", "Teams"), ("komand", "Teams"), ("team", "Teams"),
    ("zen + jun", "Juniors + Women"), ("zeny + jun", "Juniors + Women"), ("jun + zen", "Juniors + Women"),
    ("jednotliv", ""), ("individual", ""), ("zen", "Women"), ("junior", "Juniors"), ("veteran", "Veterans"),
    ("u13", "U13"), ("do 13", "U13"), ("55", "55+"), ("50", "50+"),
]


def category_of(link_text: str) -> str | None:
    text = " ".join(ascii_fold(link_text).split())
    for frag, cat in _CATEGORY_WORDS:
        if frag in text:
            return cat
    return None


def hub_links(html: str, url: str) -> list[tuple[str, str]]:
    """Category links on a championship hub page ('Turnaj jednotlivců', 'Turnaj žen', 'Veteráni', ...):
    [(category, absolute url)], one per distinct URL. Empty if the page is not a hub."""
    soup = BeautifulSoup(html, "lxml")
    out, seen = [], set()
    base_dir = url.rsplit("/", 1)[0] + "/"
    for a in soup.find_all("a", href=True):
        href = a["href"].strip()
        absolute = urljoin(url, href).split("#")[0]
        if not absolute.startswith(base_dir) or absolute in seen or re.search(r"/(index|foto)", absolute[len(base_dir):]):
            continue
        cat = category_of(a.get_text(" ", strip=True))
        if cat is None:
            continue
        seen.add(absolute)
        out.append((cat, absolute))
    return out


def collect_pages(start_url: str, start_html: str, fetch, max_pages: int = 60) -> dict[str, str]:
    """Breadth-first walk over result pages linked from ``start_url`` within the same directory (cross-tables,
    play-off, participants, final ranking). ``fetch(url) -> html | None``. Returns {url: html}."""
    base_dir = start_url.rsplit("/", 1)[0] + "/"
    pages = {start_url: start_html}
    queue = [start_html and start_url]
    while queue and len(pages) < max_pages:
        url = queue.pop(0)
        soup = BeautifulSoup(pages[url], "lxml")
        for a in soup.find_all("a", href=True):
            absolute = urljoin(url, a["href"].strip()).split("#")[0]
            if absolute in pages or not absolute.startswith(base_dir):
                continue
            rel = absolute[len(base_dir):]
            if "/" in rel or not _RESULT_PAGE.search(rel):
                continue
            html = fetch(absolute)
            pages[absolute] = html or ""
            if html:
                queue.append(absolute)
    return {u: h for u, h in pages.items() if h}


def group_signature(g: Group) -> tuple:
    """Identical tables shown on several pages (kriz.aspx, krizB.aspx, cross_1.aspx) have the same signature."""
    return tuple((r.label, tuple(r.cells)) for r in g.rows)
